public class StreamableOracle {
    static class FaultTransaction extends Transaction {
        String fault;
        public void writeDataStream(DataOutputStream out)throws IOException{if(fault==null){super.writeDataStream(out);return;}out.writeByte(42);if(fault.equals("io"))throw new IOException("fixture");if(fault.equals("runtime"))throw new IllegalArgumentException("fixture");throw new AssertionError("fixture");}
    }
    static class Failing implements Streamable {
        byte[] values={1,2,3};int fail;
        Failing(int n){fail=n;}
        public void writeDataStream(DataOutputStream out)throws IOException{for(int i=0;i<values.length;i++){if(i==fail)throw new IOException("fixture write");out.writeByte(values[i]);}if(fail==3)throw new IOException("fixture write");}
        public void readDataStream(DataInputStream in)throws IOException{for(int i=0;i<values.length;i++)values[i]=in.readByte();}
    }
    static Streamable bad(String kind){var d=new MMRData(new MiniData(new byte[65]),new MiniNumber(7));var p=new MMRProof(new MiniNumber(7));p.addProofChunk(true,d);var s=new SignatureProof(new MiniData("0xA1"),new MiniData("0xB2"),p);if(kind.equals("mmrdata"))return d;if(kind.equals("entry"))return new MMREntry(7,new MMREntryNumber(4),d);if(kind.equals("chunk"))return p.new MMRProofChunk(true,d);if(kind.equals("signatureproof"))return s;var result=new Signature();result.addSignatureProof(s);return result;}
    static Streamable objectBad(JSONObject q){String kind=q.getString("kind");var bad=new MiniData(new byte[65]);var proof=new MMRProof(new MiniNumber(7));proof.addProofChunk(true,new MMRData(bad,MiniNumber.ONE));if(kind.equals("address"))return new Address(bad);if(kind.equals("scriptproof"))return new ScriptProof("RETURN TRUE",proof);if(kind.equals("token"))return new Token(bad,MiniNumber.ONE,MiniNumber.ONE,new MiniString("name"),new MiniString("script"));String fault=q.getString("fault");var coin=new Coin(new MiniData("0x01"),fault.equals("address")?bad:new MiniData("0x02"),new MiniNumber(3),Token.TOKENID_MINIMA);if(fault.equals("coinid"))coin.resetCoinID(bad);if(fault.equals("tokenid"))coin.resetTokenID(bad);if(fault.equals("state"))coin.setState(null);if(fault.equals("token"))coin.setToken(new Token(bad,MiniNumber.ONE,MiniNumber.ONE,new MiniString("name"),new MiniString("script")));if(kind.equals("coin"))return coin;return new CoinProof(coin,fault.equals("proof")?proof:new MMRProof());}
    static Streamable create(JSONObject q)throws Exception{if(q.getString("kind").equals("transaction")){var result=new FaultTransaction();if(q.getString("op").equals("badwrite")){result.readDataStream(new DataInputStream(new ByteArrayInputStream(data(q,"base"))));String fault=q.getString("fault");if(fault.equals("link"))result.setLinkHash(new MiniData(new byte[65]));else{var child=new JSONObject();child.putAll(q);child.put("kind","coin");child.put("fault","coinid");var coin=(Coin)create(child);if(fault.equals("input"))result.addInput(coin);else result.addOutput(coin);}}return result;}if(q.getString("kind").equals("witness")){var result=new Witness();if(q.getString("op").equals("badwrite")){result.readDataStream(new DataInputStream(new ByteArrayInputStream(data(q,"base"))));String fault=q.getString("fault");var child=new JSONObject();child.putAll(q);child.put("kind",fault);if(fault.equals("signature"))result.getAllSignatures().add((Signature)create(child));else if(fault.equals("coinproof")){child.put("fault","coinid");result.addCoinProof((CoinProof)create(child));}else result.getAllScripts().add((ScriptProof)create(child));}return result;}if(q.getString("op").equals("badwrite")&&java.util.Set.of("address","scriptproof","token","coin","coinproof").contains(q.getString("kind")))return objectBad(q);if(q.getString("op").equals("badwrite"))return bad(q.getString("kind"));return switch(q.getString("kind")){case "state"->new StateVariable(1,"[seed]");case "address"->new Address("RETURN TRUE");case "scriptproof"->new ScriptProof("RETURN TRUE");case "token"->new Token(new MiniData("0x01"),MiniNumber.ZERO,MiniNumber.ONE,new MiniString("seed"),new MiniString("RETURN TRUE"));case "coin"->new Coin(new MiniData("0x00"),MiniNumber.ZERO,Token.TOKENID_MINIMA);case "coinproof"->new CoinProof(new Coin(new MiniData("0x00"),MiniNumber.ZERO,Token.TOKENID_MINIMA),new MMRProof());case "data"->new MiniData();case "number"->new MiniNumber();case "string"->new MiniString("");case "byte"->new MiniByte();case "proof"->new MMRProof();case "mmrdata"->new MMRData(new MiniData("0x"),MiniNumber.ZERO);case "entrynumber"->new MMREntryNumber();case "entry"->Boolean.TRUE.equals(q.get("nullData"))?new MMREntry(7,new MMREntryNumber(4),(MMRData)null):new MMREntry(7,new MMREntryNumber(4));case "chunk"->new MMRProof().new MMRProofChunk(false,new MMRData(new MiniData("0x"),MiniNumber.ZERO));case "signatureproof"->new SignatureProof(new MiniData("0x"),new MiniData("0x"),new MMRProof());case "signature"->new Signature();case "horst"->new HORSTSignature();case "fors"->new FORSSignature();case "sphincs"->new SPHINCSSignature();case "failing"->new Failing(((Number)q.get("fail")).intValue());default->throw new IllegalArgumentException();};}
    static byte[] data(JSONObject q,String name){return new MiniData(q.getString(name)).getBytes();}
    static String hex(byte[] bytes){return new MiniData(bytes).to0xString();}
    static JSONObject state(Streamable value){var out=new JSONObject();var buffer=new ByteArrayOutputStream();buffer.write(0xaa);buffer.write(0x55);try{value.writeDataStream(new DataOutputStream(buffer));}catch(Exception e){out.put("writeError",e.getClass().getName());}out.put("appended",hex(buffer.toByteArray()));return out;}
    static JSONObject run(JSONObject q)throws Exception{
        var result=new JSONObject();Streamable value=create(q);var initial=data(q,"initial");if(!q.getString("op").equals("badwrite")&&!Boolean.TRUE.equals(q.get("empty")))value.readDataStream(new DataInputStream(new ByteArrayInputStream(initial)));if(value instanceof MMRData d)d.setUnspendable(true);Signature alias=value instanceof Signature?(Signature)value:null;var oldList=alias==null?null:alias.getAllSignatureProofs();String op=q.getString("op");if(Boolean.TRUE.equals(q.get("cache")))((MiniData)value).getDataValue();
        Witness witnessAlias=value instanceof Witness?(Witness)value:null;var oldSignatures=witnessAlias==null?null:witnessAlias.getAllSignatures();var oldCoins=witnessAlias==null?null:witnessAlias.getAllCoinProofs();var oldScripts=witnessAlias==null?null:witnessAlias.getAllScripts();var containing=new TxPoW();if(witnessAlias!=null)containing.setWitness(witnessAlias);
        Transaction transactionAlias=value instanceof Transaction?(Transaction)value:null;var oldInputs=transactionAlias==null?null:transactionAlias.getAllInputs();var oldOutputs=transactionAlias==null?null:transactionAlias.getAllOutputs();var oldState=transactionAlias==null?null:transactionAlias.getCompleteState();var oldID=transactionAlias==null?null:transactionAlias.getTransactionID();var oldLink=transactionAlias==null?null:transactionAlias.getLinkHash();if(transactionAlias!=null){transactionAlias.mHaveCheckedMonotonic=true;transactionAlias.mIsMonotonic=true;transactionAlias.mIsValid=true;containing.setTransaction(transactionAlias);}
        if(op.equals("read")){byte[] bytes=q.containsKey("selfInput")?((MiniData)value).getBytes():data(q,"wire");var buffer=new ByteArrayInputStream(bytes);int start=((Number)q.get("offset")).intValue();buffer.skip(start);try{var in=new DataInputStream(buffer);if(q.containsKey("hashRead"))((MiniData)value).readHashFromStream(in);else if(q.containsKey("expectedSize"))((MiniData)value).readDataStream(in,((Number)q.get("expectedSize")).intValue());else value.readDataStream(in);}catch(Exception e){result.put("readError",e.getClass().getName());}result.put("offset",bytes.length-buffer.available());}
        else if(op.equals("callers")){
            result.put("data",MiniData.getMiniDataVersion(value).to0xString());result.put("hash",Crypto.getInstance().hashObject(value).to0xString());result.put("pairHash",Crypto.getInstance().hashObjects(value,value).to0xString());result.put("nio",NIOManager.createNIOMessage(new MiniByte(13),value).to0xString());
            File file=new File(q.getString("file"));try{MiniFile.writeObjectToFile(file,value);result.put("file",hex(MiniFile.readCompleteFile(file)));MiniFile.writeObjectToFile(file,value,true);result.put("appendedFile",hex(MiniFile.readCompleteFile(file)));MiniFile.writeDataToFile(file,data(q,"wire"));MiniFile.loadObject(file,value);}finally{file.delete();}
        }
        if(transactionAlias!=null){
            var t=transactionAlias;
            if(op.equals("transactionRemove"))t.removeStateVariable(((Number)q.get("port")).intValue());
            if(op.equals("transactionAdd"))t.addStateVariable(new StateVariable(1,"[replacement]"));
            if(op.equals("transactionClear"))t.clearState();
            if(op.equals("transactionFlags")){t.clearIsMonotonic();t.mIsValid=false;}
            if(op.equals("transactionNullLink"))t.setLinkHash(null);
            try{if(op.equals("transactionFault")){((FaultTransaction)value).fault=q.getString("fault");t.calculateTransactionID();}else if(op.equals("transactionNullLink"))t.calculateTransactionID();else if(op.equals("transactionJSON"))t.toJSON();}catch(Throwable error){result.put("calculationError",error.getClass().getName());}
            ((FaultTransaction)value).fault=null;
            if(q.containsKey("verifyMode")){
                String mode=q.getString("verifyMode");var sig=new Signature();var proof=new SignatureProof(new MiniData("0xA1"),new MiniData("0xB2"),new MMRProof());if(!mode.equals("empty"))sig.addSignatureProof(proof);if(mode.equals("excess"))for(int i=1;i<9;i++)sig.addSignatureProof(proof);var key=new TreeKey();key.setPublicKey(mode.equals("mismatch")?new MiniData("0x00"):proof.getRootPublicKey());
                try{boolean verified;if(mode.equals("checkerEmpty")||mode.equals("checkerProof")){if(mode.equals("checkerProof"))containing.getWitness().addSignature(sig);verified=org.minima.system.brains.TxPoWChecker.checkSignatures(containing);}else verified=key.verify(t.getTransactionID(),mode.equals("nullSignature")?null:sig);result.put("verified",verified);}catch(Exception error){result.put("verifyError",error.getClass().getName());}
            }
            var same=new JSONArray();same.add(oldInputs==t.getAllInputs());same.add(oldOutputs==t.getAllOutputs());same.add(oldState==t.getCompleteState());var counts=new JSONArray();counts.add(t.getAllInputs().size());counts.add(t.getAllOutputs().size());counts.add(t.getCompleteState().size());var flags=new JSONArray();flags.add(t.mHaveCheckedMonotonic);flags.add(t.mIsMonotonic);flags.add(t.mIsValid);
            var previous=new Transaction();previous.getAllInputs().addAll(oldInputs);previous.getAllOutputs().addAll(oldOutputs);previous.getCompleteState().addAll(oldState);previous.setLinkHash(oldLink);
            result.put("oldTransaction",state(previous));result.put("transactionAlias",state(t));result.put("containingTransaction",state(containing.getTransaction()));result.put("sameTransactionLists",same);result.put("transactionCounts",counts);result.put("transactionFlags",flags);result.put("sameID",oldID==t.getTransactionID());result.put("sameLink",oldLink==t.getLinkHash());result.put("oldID",oldID.to0xString());result.put("transactionID",t.getTransactionID()==null?null:t.getTransactionID().to0xString());var ownerFlags=new JSONArray();var containingFlags=new JSONArray();var ownerTransaction=(Transaction)value;var contained=containing.getTransaction();ownerFlags.add(ownerTransaction.mHaveCheckedMonotonic);ownerFlags.add(ownerTransaction.mIsMonotonic);ownerFlags.add(ownerTransaction.mIsValid);containingFlags.add(contained.mHaveCheckedMonotonic);containingFlags.add(contained.mIsMonotonic);containingFlags.add(contained.mIsValid);result.put("ownerFlags",ownerFlags);result.put("containingFlags",containingFlags);result.put("stateSize",t.calculateStateSize());
        }
        if(witnessAlias!=null){
            var w=witnessAlias;
            if(op.equals("witnessClear")){w.clearSignatures();w.clearCoinProofs();w.clearScriptProofs();}
            if(op.equals("witnessDuplicates")){w.addSignature(oldSignatures.get(0));w.addCoinProof(oldCoins.get(0));w.addScript(oldScripts.get(0));var keys=w.getAllSignatureKeys();keys.clear();}
            if(q.containsKey("clearHeld")){oldSignatures.clear();oldCoins.clear();oldScripts.clear();}
            var oldSizes=new JSONArray();oldSizes.add(oldSignatures.size());oldSizes.add(oldCoins.size());oldSizes.add(oldScripts.size());var sameLists=new JSONArray();sameLists.add(oldSignatures==w.getAllSignatures());sameLists.add(oldCoins==w.getAllCoinProofs());sameLists.add(oldScripts==w.getAllScripts());var currentSizes=new JSONArray();currentSizes.add(w.getAllSignatures().size());currentSizes.add(w.getAllCoinProofs().size());currentSizes.add(w.getAllScripts().size());
            var oldWitness=new Witness();oldWitness.getAllSignatures().addAll(oldSignatures);oldWitness.getAllCoinProofs().addAll(oldCoins);oldWitness.getAllScripts().addAll(oldScripts);result.put("oldState",state(oldWitness));
            result.put("oldSizes",oldSizes);result.put("sameLists",sameLists);result.put("currentSizes",currentSizes);result.put("witnessAlias",state(w));result.put("containingWitness",state(containing.getWitness()));
        }
        if(op.equals("tokenConvert")){try{result.put("converted",Token.convertMiniDataVersion(new MiniData(data(q,"wire")))!=null);}catch(Exception e){result.put("convertError",e.getClass().getName());}}
        if(value instanceof Address a)result.put("derived",a.getMinimaAddress());if(value instanceof ScriptProof p)result.put("derived",p.getAddressData().to0xString());if(value instanceof Token t)result.put("derived",t.getTokenID()==null?null:t.getTokenID().to0xString());if(value instanceof StateVariable s)result.put("stateText",s.toString());
        if(value instanceof MMREntry e)result.put("empty",e.isEmpty());if(value instanceof MMRData d)result.put("unspendable",d.isUnspendable());if(alias!=null){result.put("oldListSize",oldList.size());result.put("sameList",oldList==alias.getAllSignatureProofs());result.put("aliasCount",alias.getAllSignatureProofs().size());}
        if(value instanceof MiniData d){result.put("numeric",d.getDataValue().toString());result.put("less128",d.isLess(new MiniData("0x80")));result.put("shiftLeft",d.shiftl(1).to0xString());result.put("shiftRight",d.shiftr(1).to0xString());}
        result.put("state",state(value));return result;
    }
    public static void main(String[] args)throws Exception{var input=new BufferedReader(new InputStreamReader(System.in));String line;while((line=input.readLine())!=null){JSONObject result;var original=System.out;var captured=new ByteArrayOutputStream();System.setOut(new PrintStream(captured,true,"UTF-8"));try{result=run((JSONObject)JSONValue.parseWithException(line));}catch(Exception e){result=new JSONObject();result.put("error",e.getClass().getName());result.put("message",e.getMessage());}System.setOut(original);var logs=new JSONArray();for(String text:captured.toString("UTF-8").split("\n")){int pos=text.indexOf("] : java.");if(pos>=0){String type=text.substring(pos+4);int end=type.indexOf(": ");logs.add(end<0?type:type.substring(0,end));}}result.put("logs",logs);System.out.println(result.toJSONString());}}
}
